162	// internal generic allocation
163	static mi_decl_forceinline void* mi_theap_malloc_generic(mi_theap_t* theap, size_t size, bool zero, size_t huge_alignment, mi_page_t** ppage) mi_attr_noexcept
164	{
165	  #if MI_GUARDED
166	  #if MI_THEAP_INITASNULL
167	  if (theap!=NULL)
168	  #endif
169	  if (huge_alignment==0 && mi_theap_malloc_use_guarded(theap, size)) {
170	    return _mi_theap_malloc_guarded(theap, size, zero, ppage);
171	  }
172	  #endif
173	  #if !MI_THEAP_INITASNULL
174	  mi_assert(theap!=NULL);
175	  #endif
176	  mi_assert(mi_theap_matches_thread(theap));   // theaps are thread local
177	  mi_assert((huge_alignment & 1)==0);
178	  void* const p = _mi_malloc_generic(theap, size + MI_PADDING_SIZE, (zero ? 1 : 0) | huge_alignment, ppage);  // note: size can overflow but it is detected in malloc_generic
179	  mi_track_malloc(p, size, zero);
180	
181	  #if MI_DEBUG>3
182	  if (p != NULL && zero) {
183	    mi_assert_expensive(mi_mem_is_zero(p, size));
184	  }
185	  #endif
186	  return p;
187	}
