190	static mi_decl_forceinline mi_decl_restrict void* mi_theap_malloc_small_zero(mi_theap_t* theap, size_t size, bool zero, mi_page_t** ppage) mi_attr_noexcept {
191	  #if MI_THEAP_INITASNULL
192	  if (theap!=NULL) {
