679	/*-------------------------------------------------------
680	C++ new and new_aligned
681	The standard requires calling into `get_new_handler` and
682	throwing the bad_alloc exception on failure. If we compile
683	with a C++ compiler we can implement this precisely. If we
684	use a C compiler we cannot throw a `bad_alloc` exception
685	but we call `abort` instead (i.e. not returning).
686	Also, the standard requires calling the new handler until
687	it returns false, but we limit the total calls.
688	-------------------------------------------------------*/
689	#define MI_TRY_NEW_MAX (4)
690	
691	#ifdef __cplusplus
692	#include <new>
693	static bool mi_try_new_handler(bool nothrow) {
694	  #if defined(_MSC_VER) || (__cplusplus >= 201103L)
695	    std::new_handler h = std::get_new_handler();
696	  #else
697	    std::new_handler h = std::set_new_handler();
698	    std::set_new_handler(h);
699	  #endif
700	  if (h==NULL) {
701	    _mi_error_message(ENOMEM, "out of memory in 'new'");
702	    #if defined(_CPPUNWIND) || defined(__cpp_exceptions)  // exceptions are not always enabled
703	    if (!nothrow) {
704	      throw std::bad_alloc();
705	    }
706	    #else
707	    MI_UNUSED(nothrow);
708	    #endif
709	    return false;
710	  }
711	  else if (!nothrow) {
712	    h();
713	    return true;
714	  }
715	  else {
716	    try {
717	      h();
718	    }
719	    catch(...) {     // swallow std::bad_alloc
720	      return false;  // stop trying
721	    }
722	    return true;
723	  }
724	}
725	#else
726	typedef void (*std_new_handler_t)(void);
727	
728	#if (defined(__GNUC__) || (defined(__clang__) && !defined(_MSC_VER)))  // exclude clang-cl, see issue #631
729	std_new_handler_t __attribute__((weak)) _ZSt15get_new_handlerv(void) {
730	  return NULL;
731	}
732	static std_new_handler_t mi_get_new_handler(void) {
733	  return _ZSt15get_new_handlerv();
734	}
735	#else
736	// note: on windows we could dynamically link to `?get_new_handler@std@@YAP6AXXZXZ`.
737	static std_new_handler_t mi_get_new_handler(void) {
738	  return NULL;
739	}
740	#endif
741	
742	static bool mi_try_new_handler(bool nothrow) {
743	  std_new_handler_t h = mi_get_new_handler();
744	  if (h==NULL) {
745	    _mi_error_message(ENOMEM, "out of memory in 'new'");
746	    if (!nothrow) {
747	      abort();  // cannot throw in plain C, use abort
748	    }
749	    return false;
750	  }
751	  else {
752	    h();
753	    return true;
754	  }
755	}
756	#endif
757	
758	static mi_decl_noinline void* mi_theap_try_new(mi_theap_t* theap, size_t size, bool nothrow ) {
759	  void* p = NULL;
760	  for(int i = 0; i < MI_TRY_NEW_MAX && p == NULL && mi_try_new_handler(nothrow); i++) {
761	    if (size > MI_MAX_ALLOC_SIZE) return NULL; // call try_new_handler at least once
762	    p = mi_theap_malloc(theap,size);
763	  }
764	  return p;
765	}
